customScripts.usa_training_slider:
(function(root, ctx){
  if (!root) return;
  if (root.dataset.mfUsaTrainingSliderInit === '1') return;
  root.dataset.mfUsaTrainingSliderInit = '1';

  var slidesWrap = root.querySelector('.usa-slider-slides');
  var dotsWrap = root.querySelector('.usa-slider-dots');
  var prevBtn = root.querySelector('.usa-slider-prev');
  var nextBtn = root.querySelector('.usa-slider-next');
  var container = root.querySelector('.usa-slider-container');
  if (!slidesWrap || !dotsWrap || !prevBtn || !nextBtn || !container) return;

  var slides = Array.prototype.slice.call(slidesWrap.querySelectorAll('.usa-slide'));
  if (!slides.length) return;

  var current = 0;
  var perView = 1;
  var maxIndex = 0;
  var timer = null;
  var touchStartX = null;
  var cleanupFns = [];

  function computePerView(){
    var w = window.innerWidth || 1024;
    if (w < 480) return 1;
    if (w < 768) return 2;
    return 3;
  }

  function rebuildMetrics(){
    perView = computePerView();
    maxIndex = Math.max(0, slides.length - perView);
    if (current > maxIndex) current = maxIndex;
  }

  function renderDots(){
    dotsWrap.innerHTML = '';
    if (maxIndex <= 0) return;
    for (var i = 0; i <= maxIndex; i++){
      (function(index){
        var dot = document.createElement('button');
        dot.type = 'button';
        dot.className = 'usa-dot' + (index === current ? ' active' : '');
        dot.setAttribute('aria-label', 'Go to slide ' + (index + 1));
        dot.addEventListener('click', function(){ goTo(index); });
        dotsWrap.appendChild(dot);
      })(i);
    }
  }

  function updateNavState(){
    var shouldShowNav = maxIndex > 0;
    prevBtn.style.visibility = shouldShowNav ? 'visible' : 'hidden';
    nextBtn.style.visibility = shouldShowNav ? 'visible' : 'hidden';
    dotsWrap.style.display = shouldShowNav ? 'flex' : 'none';
  }

  function apply(){
    slidesWrap.style.transform = 'translateX(-' + (current * (100 / perView)) + '%)';
    var dots = dotsWrap.querySelectorAll('.usa-dot');
    for (var i = 0; i < dots.length; i++){
      dots[i].classList.toggle('active', i === current);
    }
    updateNavState();
  }

  function goTo(index){
    current = Math.max(0, Math.min(index, maxIndex));
    apply();
  }

  function next(){
    if (maxIndex <= 0) return;
    goTo(current >= maxIndex ? 0 : current + 1);
  }

  function prev(){
    if (maxIndex <= 0) return;
    goTo(current <= 0 ? maxIndex : current - 1);
  }

  function stopAutoplay(){
    if (timer){
      clearInterval(timer);
      timer = null;
    }
  }

  function startAutoplay(){
    stopAutoplay();
    if (maxIndex <= 0) return;
    timer = window.setInterval(next, 5000);
  }

  function onResize(){
    var oldPerView = perView;
    rebuildMetrics();
    if (oldPerView !== perView){
      renderDots();
    }
    apply();
    startAutoplay();
  }

  function onTouchStart(e){
    if (!e.touches || !e.touches.length) return;
    touchStartX = e.touches[0].clientX;
  }

  function onTouchEnd(e){
    if (touchStartX == null || !e.changedTouches || !e.changedTouches.length) return;
    var delta = e.changedTouches[0].clientX - touchStartX;
    touchStartX = null;
    if (Math.abs(delta) < 50) return;
    if (delta > 0) prev(); else next();
  }

  prevBtn.addEventListener('click', prev);
  nextBtn.addEventListener('click', next);
  container.addEventListener('mouseenter', stopAutoplay);
  container.addEventListener('mouseleave', startAutoplay);
  slidesWrap.addEventListener('touchstart', onTouchStart, { passive: true });
  slidesWrap.addEventListener('touchend', onTouchEnd, { passive: true });
  window.addEventListener('resize', onResize);

  cleanupFns.push(function(){ prevBtn.removeEventListener('click', prev); });
  cleanupFns.push(function(){ nextBtn.removeEventListener('click', next); });
  cleanupFns.push(function(){ container.removeEventListener('mouseenter', stopAutoplay); });
  cleanupFns.push(function(){ container.removeEventListener('mouseleave', startAutoplay); });
  cleanupFns.push(function(){ slidesWrap.removeEventListener('touchstart', onTouchStart); });
  cleanupFns.push(function(){ slidesWrap.removeEventListener('touchend', onTouchEnd); });
  cleanupFns.push(function(){ window.removeEventListener('resize', onResize); });
  cleanupFns.push(function(){ stopAutoplay(); delete root.dataset.mfUsaTrainingSliderInit; });

  if (ctx && typeof ctx.registerCleanup === 'function'){
    ctx.registerCleanup(cleanupFns);
  }

  rebuildMetrics();
  renderDots();
  apply();
  startAutoplay();
})(window.__mfCurrentScriptRoot, window.__mfScriptContext);

